private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Get the current head and tail of the list
    ListNode<E> head = list.getHead();
    ListNode<E> tail = list.getTail();

    // If the list is empty, return
    if (head == null) {
        return;
    }

    // Set the list's head to null to ensure that addListNode will not
    // try to update the list's head during the movement of nodes
    list.setHead(null);

    // Loop through all the nodes in the list, moving them one by one
    ListNode<E> current = head;
    while (current != null) {
        // Get the current node's next node
        ListNode<E> next = current.getNext();

        // Remove the current node from the list
        list.removeListNode(current);

        // Add the current node to this list
        addListNode(current);

        // Set the current node to the next node
        current = next;
    }

    // Set the list's tail to the original tail of the list
    list.setTail(tail);
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Lock both the source and destination lists to prevent any 
    // concurrent modifications while the nodes are being moved.
    synchronized (list) {
        synchronized (this) {
            // Iterate over the source list and remove each node from it.
            ListNode<E> currentNode = list.getFirst();
            while (currentNode != null) {
                // Store a reference to the next node in the list, since 
                // removing the current node will update its link to the 
                // next node.
                ListNode<E> nextNode = currentNode.getNext();

                // Remove the current node from the source list.
                list.removeListNode(currentNode);

                // Add the current node to the destination list.
                currentNode.setPrevious(null);
                currentNode.setNext(null);
                addListNode(currentNode);

                currentNode = nextNode;
            }
        }
    }
