    // Initialize variables
    java.util.List<Integer> suffixSum = new java.util.ArrayList<>();
    long totalSum = 0L;

    // Iterate through the list and compute the suffix sum
    for (int i = bounds.size() - 1; i >= 0; i--) {
        if (i == bounds.size() - 1) {
            suffixSum.add(bounds.get(i));
        } else {
            suffixSum.add(bounds.get(i) + suffixSum.get(i + 1));
        }
        totalSum += bounds.get(i);
    }

