private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<Integer>(keys.size());
    int maxLowerBound = 0;
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        int lowerBound = maxLowerBound;
        for (int j = i - 1; j >= 0; j--) {
            if (keys.get(j).compareTo(key) > 0) {
                lowerBound = Math.max(lowerBound, maxLowerBound - (i - j));
            }
        }
        maxLowerBound = Math.max(maxLowerBound, lowerBound);
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
}

